from aide import L, st, e, v, d, ch, li, od

UNIT = ("Écriture experte", "✒️", "Écrire avec l’aisance d’un auteur.", [

L("🧠", "L’essai critique",
  "Évaluer un argument, ses preuves et ses présupposés.",
  [st("🧠", "Un essai critique ne résume pas : il ÉVALUE. Is the argument convincing? Is the evidence reliable? What does the author assume?"),
   st("🔍", "Repérer les failles : a sweeping generalization (généralisation hâtive), a false dichotomy (faux dilemme), correlation vs causation."),
   st("⚖️", "Évaluer avec nuance : The author makes a compelling case for…, yet fails to address… / While persuasive, the argument overlooks…"),
   st("🧾", "Soutenir ta critique avec des preuves précises et des citations courtes.")],
  [e("⚖️", "The author makes a compelling case, yet fails to address the costs.", "L’auteur présente un argument convaincant, mais n’aborde pas les coûts."),
   e("🔍", "This is a sweeping generalization.", "C’est une généralisation hâtive."),
   e("📊", "The study confuses correlation with causation.", "L’étude confond corrélation et causalité."),
   e("🧩", "The argument rests on the assumption that people act rationally.", "L’argument repose sur la prémisse que les gens agissent rationnellement."),
   e("👀", "While persuasive, the essay overlooks key counterexamples.", "Bien que convaincant, l’essai néglige des contre-exemples clés.")],
  [v("🧠", "assumption", "présupposé, prémisse", "a hidden assumption"),
   v("🔍", "sweeping generalization", "généralisation hâtive", "That’s a sweeping generalization."),
   v("📊", "correlation / causation", "corrélation / causalité", "Correlation is not causation."),
   v("👀", "overlook", "négliger, ne pas voir", "The study overlooks this."),
   v("🧲", "compelling", "convaincant", "a compelling argument"),
   v("⚖️", "flawed", "défaillant, boiteux", "a flawed argument")],
  [d("Student", "I think the article is right. It has lots of statistics.", "Je pense que l’article a raison. Il a beaucoup de statistiques."),
   d("Professor", "But do the statistics prove causation?", "Mais les statistiques prouvent-elles la causalité?"),
   d("Student", "Hmm… they only show a correlation.", "Hum… elles montrent seulement une corrélation."),
   d("Professor", "Exactly. So the argument may be flawed. That’s critical reading.", "Exactement. Donc l’argument est peut-être boiteux. C’est ça, la lecture critique.")],
  "« Critique » en anglais (a critique) = une évaluation, pas forcément négative. « To criticize » = critiquer négativement.",
  [ch("Ice cream sales and drownings both rise in summer. Concluding one causes the other confuses correlation with ___.", ["causation", "coincidence", "conclusion"], 0, "correlation ≠ causation."),
   ch("« All teenagers are lazy » is a sweeping ___.", ["generalization", "assumption", "conclusion"], 0, "sweeping generalization."),
   ch("The author makes a ___ case, yet ignores the costs.", ["compelling", "compelled", "compulsory"], 0, "compelling = convaincant."),
   ch("The argument ___ an important counterexample.", ["overlooks", "overviews", "oversees"], 0, "overlook = négliger."),
   li("Correlation is not causation.", ["Correlation is not causation.", "Correlation is not caution.", "Correlation is causation."], 0, "Principe fondamental."),
   od("The argument rests on a hidden assumption", "L’argument repose sur un présupposé caché", "rest on = reposer sur.")]),

L("✂️", "La concision",
  "Éliminer les mots inutiles pour un style net.",
  [st("✂️", "Supprime les redondances : « past history » → history, « end result » → result, « free gift » → gift, « each and every » → every."),
   st("🔁", "Remplace les locutions lourdes : « in order to » → to, « at this point in time » → now, « in spite of the fact that » → although."),
   st("💪", "Préfère un verbe fort à un nom + verbe faible : « make a decision » → decide, « give consideration to » → consider."),
   st("🎯", "Coupe les intensifs vides : very, really, quite, basically. « very important » → crucial.")],
  [e("✂️", "At this point in time → Now", "En ce moment → Maintenant"),
   e("🔁", "In spite of the fact that it rained → Although it rained", "Malgré le fait qu’il ait plu → Bien qu’il ait plu"),
   e("💪", "We made a decision to → We decided to", "Nous avons pris la décision de → Nous avons décidé de"),
   e("🎯", "very important → crucial", "très important → crucial"),
   e("🗑️", "the end result → the result", "le résultat final → le résultat")],
  [v("✂️", "redundancy", "redondance", "Remove redundancies."),
   v("🧹", "wordiness", "verbosité", "Avoid wordiness."),
   v("🎯", "crucial", "crucial", "a crucial step"),
   v("💪", "strong verb", "verbe fort", "Use strong verbs."),
   v("📏", "concise", "concis", "Keep it concise."),
   v("🗑️", "filler words", "mots de remplissage", "Cut the filler words.")],
  [d("Editor", "« Due to the fact that we are currently at this point in time unable to… »", "« En raison du fait que nous sommes actuellement à ce moment-ci incapables de… »"),
   d("Writer", "Too long?", "Trop long?"),
   d("Editor", "Try: « Because we currently can’t… »", "Essaie : « Parce que nous ne pouvons pas actuellement… »"),
   d("Writer", "From fifteen words to four. Nice!", "De quinze mots à quatre. Bien!")],
  "Le français tolère plus de longueur que l’anglais. Une phrase anglaise efficace dépasse rarement 20 à 25 mots.",
  [ch("Concise version of « in order to »: ___", ["to", "for to", "so as to that"], 0, "in order to → to."),
   ch("« Past history » is redundant. Write: ___", ["history", "old history", "past"], 0, "history suffit."),
   ch("« Give consideration to » → ___", ["consider", "think of considering", "make consideration"], 0, "Verbe fort : consider."),
   ch("« At this point in time » → ___", ["now", "presently currently", "at this time point"], 0, "now."),
   li("We decided to postpone the launch.", ["We decided to postpone the launch.", "We made a decision to postpone the launch.", "We decided postpone the launch."], 0, "Verbe fort : decided."),
   od("Although it rained we went out", "Bien qu’il ait plu, nous sommes sortis", "Version concise de « in spite of the fact that ».")]),

L("🎨", "L’écriture créative",
  "Montrer plutôt que dire, et faire vivre un récit.",
  [st("🎨", "« Show, don’t tell » : au lieu de « She was nervous », écris « Her hands trembled as she reached for the door handle »."),
   st("👃", "Fais appel aux cinq sens : the smell of burnt toast, the crunch of snow, the sting of cold air."),
   st("🗣️", "Ponctuation du dialogue : “I’m leaving,” she said. “Where?” he asked. Virgule à l’intérieur des guillemets, nouvelle ligne pour chaque personnage."),
   st("🎙️", "Trouve ta voix : choix de mots, rythme et point de vue constants.")],
  [e("😰", "Her hands trembled as she reached for the door.", "Ses mains tremblaient quand elle a tendu le bras vers la porte."),
   e("❄️", "The snow crunched under his boots.", "La neige craquait sous ses bottes."),
   e("🍞", "The smell of burnt toast filled the kitchen.", "L’odeur de rôties brûlées emplissait la cuisine."),
   e("💬", "“I’m leaving,” she said quietly.", "« Je pars », dit-elle doucement."),
   e("🌅", "The sky blushed pink over the river.", "Le ciel rosissait au-dessus du fleuve.")],
  [v("🎨", "show, don’t tell", "montrer plutôt que dire", "Remember: show, don’t tell."),
   v("😰", "tremble", "trembler", "His voice trembled."),
   v("❄️", "crunch", "craquer, crisser", "the crunch of gravel"),
   v("🌫️", "imagery", "images, imagerie", "vivid imagery"),
   v("🎙️", "voice", "voix (style)", "She has a unique voice."),
   v("📖", "narrator", "narrateur", "an unreliable narrator")],
  [d("Teacher", "You wrote « He was angry ». Can you show it instead?", "Tu as écrit « Il était fâché ». Peux-tu plutôt le montrer?"),
   d("Student", "« He slammed the door so hard the windows rattled. »", "« Il a claqué la porte si fort que les fenêtres ont tremblé. »"),
   d("Teacher", "Much better! Now I can see his anger.", "Bien mieux! Maintenant, je vois sa colère."),
   d("Student", "Should I add a sound or a smell too?", "Devrais-je ajouter un son ou une odeur aussi?"),
   d("Teacher", "Yes, the senses bring a scene to life.", "Oui, les sens donnent vie à une scène.")],
  "En anglais, le dialogue utilise “ ” et la virgule se place DANS les guillemets : “Stop,” he said. Le tiret de dialogue français n’existe pas.",
  [ch("« Show, don’t ___. »", ["tell", "say", "write"], 0, "Show, don’t tell."),
   ch("Showing nervousness: ___", ["She was nervous.", "Her hands trembled.", "She felt nervous."], 1, "On montre par un détail."),
   ch("Correct dialogue punctuation: ___", ["“Stop”, he said.", "“Stop,” he said.", "— Stop, he said."], 1, "Virgule dans les guillemets."),
   ch("Descriptions that appeal to the senses create vivid ___.", ["imagery", "grammar", "punctuation"], 0, "imagery = images."),
   li("The snow crunched under his boots.", ["The snow crunched under his boots.", "The snow crushed under his boots.", "The snow crunched under his boot."], 0, "crunch = craquer."),
   od("He slammed the door and the windows rattled", "Il a claqué la porte et les fenêtres ont tremblé", "Montrer la colère.")]),

L("🧾", "La critique et la recension",
  "Écrire une critique nuancée d’un livre, d’un film ou d’un restaurant.",
  [st("🧾", "Structure : brève présentation (sans révéler la fin), points forts, points faibles, verdict."),
   st("🌟", "Éloges : gripping (captivant), beautifully shot (magnifiquement filmé), a tour de force, mouth-watering (alléchant)."),
   st("😕", "Réserves : the plot drags in the middle (s’essouffle), underdeveloped characters, overpriced."),
   st("⚖️", "Verdict nuancé : Despite its flaws, … / Worth seeing for… alone / Not for everyone, but…")],
  [e("📖", "This gripping novel kept me up all night.", "Ce roman captivant m’a tenu éveillé toute la nuit."),
   e("🎬", "Beautifully shot, the film nonetheless drags in the middle.", "Magnifiquement filmé, le film s’essouffle néanmoins au milieu."),
   e("🍝", "The pasta was mouth-watering, but the desserts were overpriced.", "Les pâtes étaient alléchantes, mais les desserts étaient trop chers."),
   e("⚖️", "Despite its flaws, it’s well worth seeing.", "Malgré ses défauts, ça vaut vraiment la peine."),
   e("🚫", "No spoilers, but the ending is unforgettable.", "Pas de divulgâcheur, mais la fin est inoubliable.")],
  [v("📖", "gripping", "captivant", "a gripping thriller"),
   v("🐢", "drag", "traîner en longueur", "The second half drags."),
   v("🍝", "mouth-watering", "alléchant", "a mouth-watering dish"),
   v("💸", "overpriced", "trop cher", "The drinks were overpriced."),
   v("🚫", "spoiler", "divulgâcheur", "No spoilers, please!"),
   v("⚖️", "flaw", "défaut", "It has a few flaws.")],
  [d("Critic", "So, what did you think of the new Denis Villeneuve film?", "Alors, qu’as-tu pensé du nouveau film de Denis Villeneuve?"),
   d("Friend", "Visually stunning, but it drags a bit in the middle.", "Visuellement époustouflant, mais il s’essouffle un peu au milieu."),
   d("Critic", "Agreed. The acting, though, is a tour de force.", "D’accord. Le jeu des acteurs, par contre, est un tour de force."),
   d("Friend", "Despite its flaws, it’s worth seeing on the big screen.", "Malgré ses défauts, ça vaut la peine de le voir sur grand écran.")],
  "« Divulgâcheur » est le mot québécois officiel pour « spoiler ». En anglais : « No spoilers! » ou « Spoiler alert! ».",
  [ch("A book you can’t put down is ___.", ["gripping", "dragging", "overpriced"], 0, "gripping = captivant."),
   ch("The movie is too long. It ___ in the middle.", ["drags", "grips", "shoots"], 0, "drag = s’essouffler."),
   ch("___ its flaws, it’s a great film.", ["Despite", "Although", "However"], 0, "Despite + nom."),
   ch("Revealing the ending is a ___.", ["spoiler", "review", "flaw"], 0, "spoiler = divulgâcheur."),
   li("The desserts were overpriced.", ["The desserts were overpriced.", "The deserts were overpriced.", "The desserts were overcooked."], 0, "overpriced = trop cher."),
   od("Despite its flaws it is worth seeing", "Malgré ses défauts, ça vaut la peine", "Verdict nuancé.")]),

L("🏛️", "L’anglais académique",
  "Écrire selon les conventions universitaires.",
  [st("🏛️", "Citer ses sources : According to Smith (2021), … / As Lee argues, … / Recent studies have shown that…"),
   st("🌫️", "Nuancer systématiquement : This may suggest… / There is some evidence that… / The findings appear to indicate…"),
   st("📚", "Vocabulaire académique : analyze, significant, framework, approach, data, hypothesis, furthermore, thus."),
   st("🚫", "À éviter : contractions, « I think », questions rhétoriques, langage familier, généralisations sans preuve.")],
  [e("📚", "According to Smith (2021), bilingualism improves memory.", "Selon Smith (2021), le bilinguisme améliore la mémoire."),
   e("🌫️", "These findings may suggest a link between sleep and learning.", "Ces résultats pourraient suggérer un lien entre le sommeil et l’apprentissage."),
   e("🏗️", "This study adopts a qualitative approach.", "Cette étude adopte une approche qualitative."),
   e("📊", "The difference was statistically significant.", "La différence était statistiquement significative."),
   e("🔗", "Furthermore, the data supports the hypothesis.", "De plus, les données appuient l’hypothèse.")],
  [v("📚", "cite", "citer", "Cite your sources."),
   v("🏗️", "framework", "cadre (théorique)", "a theoretical framework"),
   v("🔬", "hypothesis", "hypothèse", "Test the hypothesis."),
   v("📊", "significant", "significatif, important", "a significant increase"),
   v("🧭", "approach", "approche", "a new approach"),
   v("🔗", "thus", "ainsi, donc", "Thus, the theory holds.")],
  [d("Supervisor", "Your draft says « I think bilingual kids are smarter ».", "Ton brouillon dit « Je pense que les enfants bilingues sont plus intelligents »."),
   d("Student", "Is that too informal?", "Est-ce trop familier?"),
   d("Supervisor", "Yes. Try « Several studies suggest that bilingualism may enhance cognitive flexibility », with citations.", "Oui. Essaie « Plusieurs études suggèrent que le bilinguisme pourrait améliorer la flexibilité cognitive », avec des références."),
   d("Student", "Much more academic. Thanks!", "Beaucoup plus universitaire. Merci!")],
  "« Significant » en anglais académique a souvent un sens statistique précis. Pour « important » au sens général, préfère « substantial » ou « considerable ».",
  [ch("___ to Smith (2020), the effect is small.", ["According", "Following", "As per to"], 0, "According to + source."),
   ch("Academic hedging: « The results ___ suggest a link. »", ["may", "definitely", "obviously"], 0, "may = nuance."),
   ch("Avoid in academic writing: ___", ["contractions", "citations", "data"], 0, "Pas de contractions."),
   ch("This study adopts a qualitative ___.", ["approach", "approaching", "approval"], 0, "approach = approche."),
   li("The difference was statistically significant.", ["The difference was statistically significant.", "The difference was statistically insignificant.", "The difference is statistically significant."], 0, "Langage académique."),
   od("These findings may suggest a link", "Ces résultats pourraient suggérer un lien", "Nuance académique.")]),
])
